def render(input_path,output_path):
    inputs=json.loads(Path(input_path).read_text())
    assert {s["oracle_id"] for s in inputs}==set(RULES)
    final=[]
    for raw in inputs:
        spec=dict(raw);rule=RULES[spec["oracle_id"]]
        spec["observed_state_locations"]=spec.pop("state_locations")
        spec["state_locations"]=rule["locations"]
        spec["expected_reads"]=rule["reads"];spec["expected_writes"]=rule["writes"]
        spec["expected_def_use"]=rule["def_use"];spec["expected_unknown"]=rule["unknown"]
        spec["forbidden_dependencies"]=rule["forbidden"]
        spec["expected_support_policy"]=rule["support"]
        spec["expectation_author"]="Codex source-semantic review; independent approval pending"
        spec["observed_support_status"]=spec.pop("support_status")
        spec["support_status"]="candidate_not_independently_approved"
        final.append(spec)
    with Path(output_path).open("x",encoding="utf8") as f:json.dump({
        "status":"static_candidates_not_independently_approved","count":len(final),
        "raw_observations_sha256":hashlib.sha256(Path(input_path).read_bytes()).hexdigest(),
        "rules_are_not_derived_from_labels_or_predictions":True,"oracles":final},f,ensure_ascii=False,indent=2)
